sp_widget.client_script:
api.controller = function($scope, $window, spUtil) {
    $scope.submitRequest = function() {
        $scope.server.get({action: "submit"}).then(function(response) {
            if (response.success) {
                spUtil.addInfoMessage("Request submitted successfully!");
                $window.location.href = 'hr_dashboard_hub'; // Change to your actual dashboard page ID
            } else {
                spUtil.addErrorMessage("Error submitting request.");
            }
        });
    };
};

sp_widget.css:
.quick-actions {
  background-color: white;
  text-align: center;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-bottom: 20px;
}

.quick-actions h2 {
  color: #004080;
  margin-bottom: 15px;
}

.actions-container {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 15px;
}

.btn-action {
  background-color: #ffcc00;
  color: #004080;
  padding: 12px 20px;
  font-size: 16px;
  border-radius: 5px;
  text-decoration: none;
  font-weight: bold;
}

.btn-action:hover {
  background-color: #e6b800;
}

sp_widget.script:
(function() {
  data.approvals = [];

  // Check if user is a manager (can approve)
  var userID = gs.getUserID();
  var gr = new GlideRecord("sysapproval_approver"); // Correct table

  gr.addQuery("approver", userID); // Get approvals assigned to the logged-in user
  gr.addQuery("state", "requested"); // Only fetch pending approvals
  gr.orderByDesc("sys_created_on");
  gr.query();

  while (gr.next()) {
    var approval = {
      task: gr.sysapproval.getDisplayValue(), // Task name
      type: gr.sysapproval.sys_class_name.toString(), // Type of approval
      state: gr.state.getDisplayValue(), // Approval state
      requested_for: gr.sysapproval.requested_for.getDisplayValue(), // Requested for user
      sys_id: gr.sys_id.toString() // Approval ID for reference
    };
    data.approvals.push(approval);
  }
})();
